require __DIR__.'/../app/bootstrap.php';require_permission('roles.manage');$msg=$err=null;$actor=current_user();$super=is_super_admin($actor);$registry=permission_registry();$groups=permission_groups();$templates=role_templates();
function rbac_role_permissions(int $id): array {try{$q=db()->prepare("SELECT permissions_json FROM system_roles WHERE id=? LIMIT 1");$q->execute([$id]);$p=json_decode((string)($q->fetchColumn()?:'[]'),true);return is_array($p)?$p:[];}catch(Throwable $e){return [];}}
function rbac_assert_manageable(array $perms,array $actor,bool $super): void {if($super)return;foreach($perms as $perm)if(!has_permission((string)$perm,$actor))throw new RuntimeException('You cannot grant or modify permissions above your own access level.');}
if($_SERVER['REQUEST_METHOD']==='POST'){try{csrf_check();$action=(string)($_POST['action']??'save');$id=(int)($_POST['id']??0);if($action==='delete'){rbac_assert_manageable(rbac_role_permissions($id),$actor,$super);$q=db()->prepare("SELECT COUNT(*) FROM user_profiles WHERE custom_role_id=?");$q->execute([$id]);if((int)$q->fetchColumn()>0)throw new RuntimeException('Role is assigned to users. Reassign those users first.');db()->prepare("DELETE FROM system_roles WHERE id=?")->execute([$id]);$msg='Role deleted.';}else{$name=trim((string)($_POST['name']??''));$slug=strtolower(trim((string)preg_replace('/[^a-z0-9-]+/i','-',($_POST['slug']??'')),'-'));if(!$name||!$slug)throw new RuntimeException('Name and slug are required.');$perms=array_values(array_unique(array_intersect(array_keys($registry),$_POST['permissions']??[])));rbac_assert_manageable($perms,$actor,$super);$status=isset($_POST['status'])?1:0;if($id)db()->prepare("UPDATE system_roles SET name=?,slug=?,description=?,permissions_json=?,status=? WHERE id=?")->execute([$name,$slug,trim((string)($_POST['description']??'')),json_encode($perms),$status,$id]);else db()->prepare("INSERT INTO system_roles(name,slug,description,permissions_json,status) VALUES(?,?,?,?,?)")->execute([$name,$slug,trim((string)($_POST['description']??'')),json_encode($perms),$status]);$msg='Role saved.';}}catch(Throwable $e){$err=$e->getMessage();}}
$edit=null;$ep=[];$template=(string)($_GET['template']??'');if(isset($_GET['edit'])){$q=db()->prepare("SELECT * FROM system_roles WHERE id=?");$q->execute([(int)$_GET['edit']]);$edit=$q->fetch();$ep=$edit?json_decode((string)$edit['permissions_json'],true):[];if(!is_array($ep))$ep=[];rbac_assert_manageable($ep,$actor,$super);}elseif(isset($templates[$template])){$edit=['name'=>$templates[$template]['name'],'slug'=>$templates[$template]['slug'],'description'=>$templates[$template]['description'],'status'=>1];$ep=$templates[$template]['permissions'];}
$rows=db()->query("SELECT sr.*,(SELECT COUNT(*) FROM user_profiles up WHERE up.custom_role_id=sr.id) users_count FROM system_roles sr ORDER BY sr.name")->fetchAll();$core=core_role_registry();
require __DIR__.'/../app/layout.php';page_start('Roles & Permissions',true);
?><link rel="stylesheet" href="/assets/rbac-admin-3.3.0.css?v=330"><div class="rbac-hero"><div><span>COMMERCIAL RBAC</span><h2>Roles, Permissions & Staff Access</h2><p>Create Admin, Editor, Blogger, Shopkeeper and User accounts with controlled access. Every major dashboard/module is represented in the permission matrix.</p></div><a class="btn" href="/admin/users.php">Manage Users ↗</a></div><?php if($msg):?><div class="success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="error"><?=e($err)?></div><?php endif;?>
<section class="rbac-core-grid"><?php foreach($core as $key=>$r):?><article><div class="rbac-core-top"><i><?=e(strtoupper(substr($r['label'],0,2)))?></i><span class="<?=$r['admin_access']?'staff':'public'?>"><?=$r['admin_access']?'STAFF':'PUBLIC'?></span></div><h3><?=e($r['label'])?></h3><p><?=e($r['description'])?></p><small><?=e(count($r['permissions']))?> default permissions</small></article><?php endforeach;?></section>
<div class="rbac-security-note"><b>Commercial RBAC guard:</b> non-Super-Admin role managers can only create/edit roles using permissions they already possess. This prevents privilege escalation.</div><section class="card"><div class="rbac-head"><div><h3>Quick Role Templates</h3><span>Start from a safe commercial template, then customize permissions.</span></div></div><div class="rbac-template-row"><?php foreach($templates as $k=>$v):?><a href="?template=<?=e($k)?>"><b><?=e($v['name'])?></b><span><?=e(count($v['permissions']))?> permissions</span></a><?php endforeach;?></div></section>
<div class="rbac-layout"><section class="card rbac-editor"><div class="rbac-head"><div><h3><?=$edit&&!isset($_GET['template'])?'Edit Role':'Create Custom Role'?></h3><span>Custom roles can be assigned to any core account type.</span></div></div><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=e(isset($_GET['edit'])?($edit['id']??0):0)?>"><div class="rbac-fields"><div><label>Name</label><input class="input" name="name" value="<?=e($edit['name']??'')?>" required></div><div><label>Slug</label><input class="input" name="slug" value="<?=e($edit['slug']??'')?>" required></div></div><label>Description</label><textarea class="input" rows="2" name="description"><?=e($edit['description']??'')?></textarea><div class="rbac-matrix"><?php foreach($groups as $group=>$keys):?><fieldset><legend><?=e($group)?></legend><div><?php foreach($keys as $key):if(!isset($registry[$key]))continue;?><label><input type="checkbox" name="permissions[]" value="<?=e($key)?>" <?=in_array($key,$ep,true)?'checked':''?>><span><b><?=e($registry[$key])?></b><small><?=e($key)?></small></span></label><?php endforeach;?></div></fieldset><?php endforeach;?></div><div class="rbac-save"><label><input type="checkbox" name="status" <?=($edit['status']??1)?'checked':''?>> Active role</label><button class="btn">Save Role</button></div></form></section>
<aside class="card"><div class="rbac-head"><div><h3>Custom Roles</h3><span>Assigned user counts and access size.</span></div></div><div class="rbac-role-list"><?php foreach($rows as $r):$p=json_decode($r['permissions_json']?:'[]',true)?:[];?><article><div><b><?=e($r['name'])?></b><small><?=e($r['slug'])?> · <?=e(count($p))?> permissions</small></div><span><?=e($r['users_count'])?> users</span><a href="?edit=<?=e($r['id'])?>">Edit</a><?php if((int)$r['users_count']===0):?><form method="post" onsubmit="return confirm('Delete this role?')"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=e($r['id'])?>"><button>Delete</button></form><?php endif;?></article><?php endforeach;?></div></aside></div><?php require __DIR__.'/../app/end.php';?>